export type ErpWizardCredentialsWritable = {
    connection_type: ErpConnectionMode;
    db_type?: ErpDbType;
    host?: string;
    port?: string;
    database?: string;
    username?: string;
    password_configured?: boolean;
    ssl_enabled?: boolean;
    api_base_url?: string;
    api_auth_type?: 'api_key' | 'bearer' | 'basic' | 'oauth2';
    api_token_configured?: boolean;
    agent_install_token?: string;
    agent_connected?: boolean;
    /**
     * Senha DB — só no wizard (nunca persistida).
     */
    password?: string;
    /**
     * Token API — só no wizard (nunca persistida).
     */
    api_token?: string;
    /**
     * URL do token endpoint OAuth2 (ex. accounts.tiny.com.br/.../token).
     */
    oauth_token_url?: string;
    oauth_client_id?: string;
    /**
     * Client secret OAuth2 — só no wizard (vai ao vault).
     */
    oauth_client_secret?: string;
    /**
     * Refresh token OAuth2 — só no wizard (vai ao vault; rotação persiste lá).
     */
    oauth_refresh_token?: string;
    /**
     * true quando o vault já tem client/secret/refresh deste tenant.
     */
    oauth_configured?: boolean;
};

